mapper.update:
UPDATE content.project SET name = #{name}, description = #{description}, aspect_ratio = #{aspectRatio},
  revision = revision + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{actorId}
WHERE workspace_id = #{workspaceId} AND id = #{projectId}
  AND revision = #{expectedRevision} AND archived_at IS NULL

UPDATE content.project SET archived_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP,
  revision = revision + 1, updated_by = #{actorId}
WHERE workspace_id = #{workspaceId} AND id = #{projectId}
  AND revision = #{expectedRevision} AND archived_at IS NULL

mapper.select:
SELECT  FROM content.shot s
INNER JOIN content.shot_revision r
  ON r.workspace_id = s.workspace_id AND r.shot_id = s.id AND r.revision = s.current_revision
WHERE s.workspace_id = #{workspaceId} AND s.project_id = #{projectId} AND s.shot_number > #{afterNumber}
ORDER BY s.shot_number LIMIT #{limit}

SELECT  FROM content.shot s
INNER JOIN content.shot_revision r ON r.workspace_id = s.workspace_id AND r.shot_id = s.id
WHERE s.workspace_id = #{workspaceId} AND s.id = #{shotId} AND r.revision = #{revision}
